// namingColumns reads a library row's two naming columns straight from the
// store (the write-side truth the 400 shapes assert against).
func namingColumns(t *testing.T, st *store.Store, id int64) (groupStyle, elementName string) {
	t.Helper()
	lib, err := st.GetLibrary(context.Background(), id)
	if err != nil {
		t.Fatalf("GetLibrary: %v", err)
	}
	return lib.NamingGroupStyle, lib.NamingElementName
}

// namingWireFields pulls a served library body's two naming fields, failing
// when either is ABSENT — the wire contract is always-present flat strings,
// "" = module default.
func namingWireFields(t *testing.T, body map[string]json.RawMessage) (groupStyle, elementName string) {
	t.Helper()
	for _, key := range []string{"naming_group_style", "naming_element_name"} {
		if _, ok := body[key]; !ok {
			t.Fatalf("%s field absent from served library body", key)
		}
	}
	if err := json.Unmarshal(body["naming_group_style"], &groupStyle); err != nil {
		t.Fatalf("decode naming_group_style: %v", err)
	}
	if err := json.Unmarshal(body["naming_element_name"], &elementName); err != nil {
		t.Fatalf("decode naming_element_name: %v", err)
	}
	return groupStyle, elementName
}

// rawLibrary decodes a bare libraryDTO response body (the GET and PATCH
// library responses carry the DTO unwrapped) into a generic map.
func rawLibrary(t *testing.T, resp *http.Response) map[string]json.RawMessage {
	t.Helper()
	defer resp.Body.Close()
	var m map[string]json.RawMessage
	if err := json.NewDecoder(resp.Body).Decode(&m); err != nil {
		t.Fatalf("decode library body: %v", err)
	}
	return m
}

// TestLibraryPatchNaming covers display-naming 3.2: the library wire shape
// always carries both naming fields ("" = module default); PATCH validates
// BEFORE any write (a bad group style or a foreign {...} group is 400 with
// the stored columns unchanged); nil changes nothing; a non-nil "" resets to
// the module default; and a changed option re-composes display_names on the
// NEXT read — pure read-time composition, no rebuild step.
func TestLibraryPatchNaming(t *testing.T) {
	h, st := newLibraryAPI(t)
	ctx := context.Background()
	id, err := st.CreateLibrary(ctx, "serial", "/media/naming", "Naming")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	path := "/api/v1/libraries/" + itoa64(id)

	t.Run("naming_fields_always_on_wire_empty_is_module_default", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, path, "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		g, e := namingWireFields(t, rawLibrary(t, resp))
		if g != "" || e != "" {
			t.Fatalf("fresh library naming fields = %q/%q, want \"\"/\"\"", g, e)
		}
	})

	t.Run("valid_options_persist_and_reflect", func(t *testing.T) {
		body := `{"naming_group_style":"raw","naming_element_name":"{title} S{season}E{episode}"}`
		resp := doRequest(t, h, http.MethodPatch, path, body, adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		g, e := namingWireFields(t, rawLibrary(t, resp))
		if g != "raw" || e != "{title} S{season}E{episode}" {
			t.Fatalf("patched DTO naming fields = %q/%q", g, e)
		}
		if sg, se := namingColumns(t, st, id); sg != "raw" || se != "{title} S{season}E{episode}" {
			t.Fatalf("stored naming columns = %q/%q", sg, se)
		}
	})

	t.Run("invalid_group_style_400_columns_unchanged", func(t *testing.T) {
		body := `{"naming_group_style":"pretty"}`
		resp := doRequest(t, h, http.MethodPatch, path, body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" || eb.Error.Retryable {
			t.Fatalf("error body = %+v, want bad_request/non-retryable", eb.Error)
		}
		if sg, se := namingColumns(t, st, id); sg != "raw" || se != "{title} S{season}E{episode}" {
			t.Fatalf("rejected PATCH mutated the columns: %q/%q", sg, se)
		}
	})

	t.Run("invalid_element_template_400_columns_unchanged", func(t *testing.T) {
		cases := []struct {
			name string
			tmpl string
		}{
			{"unknown_group", "{title} {unknown}"},
			{"episode_end_group_deferred", "{title} E{episode_end}"},
			{"empty_group", "{} S{episode}"},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				body, err := json.Marshal(map[string]string{"naming_element_name": tc.tmpl})
				if err != nil {
					t.Fatalf("marshal: %v", err)
				}
				resp := doRequest(t, h, http.MethodPatch, path, string(body), adminToken)
				defer resp.Body.Close()
				if resp.StatusCode != http.StatusBadRequest {
					t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
				}
				if sg, se := namingColumns(t, st, id); sg != "raw" || se != "{title} S{season}E{episode}" {
					t.Fatalf("rejected PATCH mutated the columns: %q/%q", sg, se)
				}
			})
		}
	})

	t.Run("nil_fields_change_nothing", func(t *testing.T) {
		body := `{"display_name":"переименовали"}`
		resp := doRequest(t, h, http.MethodPatch, path, body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if sg, se := namingColumns(t, st, id); sg != "raw" || se != "{title} S{season}E{episode}" {
			t.Fatalf("nil naming fields changed the columns: %q/%q", sg, se)
		}
	})

	t.Run("empty_string_resets_to_module_default", func(t *testing.T) {
		body := `{"naming_group_style":"","naming_element_name":""}`
		resp := doRequest(t, h, http.MethodPatch, path, body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if sg, se := namingColumns(t, st, id); sg != "" || se != "" {
			t.Fatalf("stored naming columns after reset = %q/%q, want \"\"/\"\"", sg, se)
		}
		g, e := namingWireFields(t, rawLibrary(t, doRequest(t, h, http.MethodGet, path, "", adminToken)))
		if g != "" || e != "" {
			t.Fatalf("served naming fields after reset = %q/%q, want \"\"/\"\"", g, e)
		}
	})

	// Option-driven re-compose at unit level: the namer built per read picks
	// up the freshly patched option; composition is read-time only.
	t.Run("options_recompose_on_next_read", func(t *testing.T) {
		a := &app{deps: Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
			return scan.Result{}, nil
		}}}
		seedSeries(t, st, id, "Атланта (2016)", `{"sources":{"serial-parser":{"title":"Атланта"}}}`, "ready")
		doc := `{"parsed":{"series_relative_path":"Атланта (2016)"},"sources":{"serial-parser":{"season":2,"episode":6}},"_view":{"title":{"value":"файловое имя"}}}`
		it := store.Item{Document: json.RawMessage(doc)}
		patchTmpl := func(tmpl string) {
			t.Helper()
			body, err := json.Marshal(map[string]string{"naming_element_name": tmpl})
			if err != nil {
				t.Fatalf("marshal: %v", err)
			}
			resp := doRequest(t, h, http.MethodPatch, path, string(body), adminToken)
			resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("PATCH template %q: status = %d, want %d", tmpl, resp.StatusCode, http.StatusOK)
			}
		}
		patchTmpl("{title} · S{season}E{episode}")
		n, err := a.namerFor(ctx, id)
		if err != nil {
			t.Fatalf("namerFor: %v", err)
		}
		if got := n.itemName(it, ""); got != "Атланта · S02E06" {
			t.Fatalf("composed = %q, want %q", got, "Атланта · S02E06")
		}
		// A DIFFERENT option re-composes the same document on the next read.
		patchTmpl("{season}x{episode} — {title}")
		n, err = a.namerFor(ctx, id)
		if err != nil {
			t.Fatalf("namerFor: %v", err)
		}
		if got := n.itemName(it, ""); got != "02x06 — Атланта" {
			t.Fatalf("re-composed = %q, want %q", got, "02x06 — Атланта")
		}
	})
}

// TestModuleDefaultItemName covers display-naming 3.2/3.3 module-default
// layering: namerFor resolves the ACTIVE template as the library's
// naming_element_name option when set, ELSE the module default
// (ModulePresentation.ItemName through the nil-safe Deps closure), else no
// composition — the floor applies.
func TestModuleDefaultItemName(t *testing.T) {
	st := openAPIStore(t)
	ctx := context.Background()
	libID, err := st.CreateLibrary(ctx, "serial", "/media/moddefault", "ModDefault")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	seedSeries(t, st, libID, "Ход королевской кобры",
		`{"sources":{"serial-parser":{"title":"Ход королевской кобры"}}}`, "ready")
	it := store.Item{Document: json.RawMessage(`{"parsed":{"series_relative_path":"Ход королевской кобры"},"sources":{"serial-parser":{"season":1,"episode":3}},"_view":{"title":{"value":"файловое имя"}}}`)}

	newApp := func(mp ModulePresentation, mpErr error) *app {
		return &app{deps: Deps{
			AdminToken: adminToken, Store: st,
			Scan: func(context.Context, int64) (scan.Result, error) { return scan.Result{}, nil },
			ModulePresentation: func(context.Context, string, int64) (ModulePresentation, error) {
				return mp, mpErr
			},
		}}
	}

	t.Run("module_default_composes_when_no_library_option", func(t *testing.T) {
		a := newApp(ModulePresentation{ItemName: "{title} · S{season}E{episode}"}, nil)
		n, err := a.namerFor(ctx, libID)
		if err != nil {
			t.Fatalf("namerFor: %v", err)
		}
		if n.elementTmpl != "{title} · S{season}E{episode}" {
			t.Fatalf("elementTmpl = %q, want the module default", n.elementTmpl)
		}
		if got := n.itemName(it, ""); got != "Ход королевской кобры · S01E03" {
			t.Fatalf("composed = %q, want the module-default composition", got)
		}
	})

	t.Run("library_option_beats_module_default", func(t *testing.T) {
		if _, err := st.UpdateLibrary(ctx, libID, nil, nil, nil, nil, strPtr("{season}x{episode}")); err != nil {
			t.Fatalf("UpdateLibrary option: %v", err)
		}
		a := newApp(ModulePresentation{ItemName: "{title} · S{season}E{episode}"}, nil)
		n, err := a.namerFor(ctx, libID)
		if err != nil {
			t.Fatalf("namerFor: %v", err)
		}
		if n.elementTmpl != "{season}x{episode}" {
			t.Fatalf("elementTmpl = %q, want the library option", n.elementTmpl)
		}
		if got := n.itemName(it, ""); got != "01x03" {
			t.Fatalf("composed = %q, want the option-driven composition", got)
		}
		if _, err := st.UpdateLibrary(ctx, libID, nil, nil, nil, nil, strPtr("")); err != nil {
			t.Fatalf("reset option: %v", err)
		}
	})

	t.Run("nil_closure_means_no_composition", func(t *testing.T) {
		a := &app{deps: Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
			return scan.Result{}, nil
		}}}
		n, err := a.namerFor(ctx, libID)
		if err != nil {
			t.Fatalf("namerFor: %v", err)
		}
		if n.elementTmpl != "" {
			t.Fatalf("elementTmpl = %q, want \"\" (no template)", n.elementTmpl)
		}
		if got := n.itemName(it, ""); got != "файловое имя" {
			t.Fatalf("display = %q, want the _view floor", got)
		}
	})

	t.Run("empty_module_default_no_composition", func(t *testing.T) {
		a := newApp(ModulePresentation{}, nil)
		n, err := a.namerFor(ctx, libID)
		if err != nil {
			t.Fatalf("namerFor: %v", err)
		}
		if got := n.itemName(it, ""); got != "файловое имя" {
			t.Fatalf("display = %q, want the _view floor", got)
		}
	})

	t.Run("closure_error_propagates", func(t *testing.T) {
		a := newApp(ModulePresentation{}, context.DeadlineExceeded)
		if _, err := a.namerFor(ctx, libID); err == nil {
			t.Fatalf("namerFor = nil error, want the closure error propagated")
		}
	})
}
